def compute(vars):
    annual_maturities_2015 = vars["v1"]
    total_recourse_debt = vars["v2"]
    if total_recourse_debt == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}}}

    ratio = annual_maturities_2015 / total_recourse_debt
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "ratio": ratio,
            "annual_maturities_2015": annual_maturities_2015,
            "total_recourse_debt": total_recourse_debt,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"},
        },
    }
